    op=(c['ch01']<<3)|(c['ch03']<<2)|(c['ch06']<<1)|c['ch13']
    rs=(c['ch08']<<1)|c['ch10']
    rd=(c['ch15']<<1)|c['ch12']
    return op,rs,rd
def run(OPS,verbose=False,segsel=None):
    errs=[]
    for si,s in enumerate(segs):
        if not s or (segsel and si not in segsel): continue
        regs=[0,0,0,0] if si>0 else [None]*4
        flag=0 if si>0 else None
        for (t,bb,o,f) in s:
            d=dec(t)
            if d[0]=='L':
                rd=d[1]
                regs[rd]=None if regs[rd] is None else ((regs[rd]<<4)|d[2])&M
                if flag is not None and f!=flag: errs.append((t,'Lflag'))
                flag=f; continue
            if d[0]==13:
                v=internal(o)
                if regs[d[1]] is not None and regs[d[1]]!=v: errs.append((t,'out',d[1],'%02x'%regs[d[1]],'%02x'%v))
                if flag is not None and f!=flag: errs.append((t,'OUTflag'))
                regs[d[1]]=v; flag=f; continue
            op,rs,rd=d
            fn=OPS.get(op)
            if fn is None: regs[rd]=None; flag=f; continue
            a,b=regs[rd],regs[rs]
            res=fn(a,b,flag)   # returns (write?, value or None, flag or None)  
            w,val,nf=res
            if nf is not None and nf!=f: errs.append((t,'flag',op,f))
            if w: regs[rd]=val
